function draftRow(d){return d.source==='lab'?`<article class="list-item"><b>${esc(d.title)}</b>${d.visibility==='private'?`<small> ${esc(emuT('k.panel.private'))}</small>`:''}<p>${esc(String(d.body||'').slice(0,100))}</p><div class="draft-actions"><button data-open-lab-draft="${esc(d.id)}">${esc(emuT('k.panel.openInLab'))}</button></div></article>`:`<article class="list-item"><b>${esc(d.title)}</b><p>${esc(String(d.body||'').slice(0,100))}</p><div class="draft-actions"><button data-edit-draft="${esc(d.id)}">${esc(emuT('k.panel.edit'))}</button><button data-delete-draft="${esc(d.id)}">${esc(emuT('k.panel.delete'))}</button></div></article>`}
/* LAB-04・下書きの表示統合（11/7）：通常の下書きと Knowledge Lab の下書き・自分用を、置き場所はそのままに並べる。
   30件ずつで、続きは「もっと見る」。保存枠（両方の合計）と件数も出す。 */
function bindDraftActions(){document.querySelectorAll('[data-edit-draft]').forEach(b=>b.onclick=()=>editDraft(b.dataset.editDraft));document.querySelectorAll('[data-delete-draft]').forEach(b=>b.onclick=()=>send({type:'emu-knowledge-delete-draft',draftId:b.dataset.deleteDraft}));document.querySelectorAll('[data-open-lab-draft]').forEach(b=>b.onclick=()=>send({type:'emu-knowledge-open-lab-draft',draftId:b.dataset.openLabDraft}));document.querySelectorAll('[data-more-drafts]').forEach(b=>b.onclick=()=>{b.disabled=true;send({type:'emu-knowledge-more-drafts',source:b.dataset.moreDrafts,cursor:b.dataset.cursor})})}
function renderPanel(kind,items){if(kind==='library'){const posts=items.posts||[],drafts=items.drafts||[],lab=items.labDrafts||[];state.panelDrafts=drafts;const usage=Number.isFinite(items.libraryUsed)&&items.libraryCap?`<p class="locked-note">${esc(emuT('k.panel.libraryUsage',{used:items.libraryUsed,cap:items.libraryCap}))}</p>`:'';const more=(source,cursor)=>cursor?`<div class="draft-actions" data-more-wrap="${source}"><button data-more-drafts="${source}" data-cursor="${esc(cursor)}">${esc(emuT('k.panel.more'))}</button></div>`:'';$('#panelList').innerHTML=`<h3>${esc(emuT('k.panel.myPosts'))}</h3>${posts.length?posts.map(p=>`<article class="list-item"><b>${esc(p.title)}</b><small> Good ${p.goodCount||0}・Change ${p.changeCount||0}</small>${p.id?`<div class="draft-actions"><button data-delete-mypost="${esc(p.id)}">${esc(emuT('k.action.delete'))}</button></div>`:''}</article>`).join(''):`<p>${esc(emuT(items.postsUnread?'k.panel.postsUnread':'k.panel.noPosts'))}</p>`}<h3>${esc(emuT('k.panel.drafts'))}${Number.isFinite(items.draftsTotal)?` <small>${esc(emuT('k.panel.draftsCount',{n:items.draftsTotal}))}</small>`:''}</h3>${usage}<div id="emuDraftList">${drafts.length?drafts.map(draftRow).join(''):`<p>${esc(emuT('k.panel.noDrafts'))}</p>`}</div>${more('emu',items.draftsNext)}<h3>${esc(emuT('k.panel.labDrafts'))}</h3><div id="labDraftList">${lab.length?lab.map(draftRow).join(''):`<p>${esc(emuT(items.labDraftsUnread?'k.panel.labUnread':'k.panel.noLabDrafts'))}</p>`}</div>${more('lab',items.labDraftsNext)}`;bindDraftActions();document.querySelectorAll('[data-delete-mypost]').forEach(b=>b.onclick=()=>send({type:'emu-knowledge-delete-post',postId:b.dataset.deleteMypost,fromLibrary:true}))}else{const rows=Array.isArray(items)?items:[];$('#panelList').innerHTML=rows.length?rows.map((row,i)=>`<article class="list-item"><b>${i+1}. ${esc(row.displayName||row.address||emuT('k.anonymous'))}</b><small>${esc(row.scoreLabel||String(row.score||0))}</small></article>`).join(''):`<p>${esc(emuT('k.panel.noRanking'))}</p>`}}
function renderPanel(kind,items){if(kind==='library'){const posts=items.posts||[],drafts=items.drafts||[];state.panelDrafts=drafts;$('#panelList').innerHTML=`<h3>${esc(emuT('k.panel.myPosts'))}</h3>${posts.length?posts.map(p=>`<article class="list-item"><b>${esc(p.title)}</b><small> Good ${p.goodCount||0}・Change ${p.changeCount||0}</small>${p.id?`<div class="draft-actions"><button data-delete-mypost="${esc(p.id)}">${esc(emuT('k.action.delete'))}</button></div>`:''}</article>`).join(''):`<p>${esc(emuT(items.postsUnread?'k.panel.postsUnread':'k.panel.noPosts'))}</p>`}<h3>${esc(emuT('k.panel.drafts'))}</h3>${drafts.length?drafts.map(d=>`<article class="list-item"><b>${esc(d.title)}</b><p>${esc(String(d.body||'').slice(0,100))}</p><div class="draft-actions"><button data-edit-draft="${esc(d.id)}">${esc(emuT('k.panel.edit'))}</button><button data-delete-draft="${esc(d.id)}">${esc(emuT('k.panel.delete'))}</button></div></article>`).join(''):`<p>${esc(emuT('k.panel.noDrafts'))}</p>`}`;document.querySelectorAll('[data-edit-draft]').forEach(b=>b.onclick=()=>editDraft(b.dataset.editDraft));document.querySelectorAll('[data-delete-draft]').forEach(b=>b.onclick=()=>send({type:'emu-knowledge-delete-draft',draftId:b.dataset.deleteDraft}));document.querySelectorAll('[data-delete-mypost]').forEach(b=>b.onclick=()=>send({type:'emu-knowledge-delete-post',postId:b.dataset.deleteMypost,fromLibrary:true}))}else{const rows=Array.isArray(items)?items:[];$('#panelList').innerHTML=rows.length?rows.map((row,i)=>`<article class="list-item"><b>${i+1}. ${esc(row.displayName||row.address||emuT('k.anonymous'))}</b><small>${esc(row.scoreLabel||String(row.score||0))}</small></article>`).join(''):`<p>${esc(emuT('k.panel.noRanking'))}</p>`}}
window.addEventListener('message',e=>{if(e.origin!==ORIGIN||e.source!==parent)return;const m=e.data||{};if(m.type==='emu-knowledge-filter'){const map={recommended:'recommended',recommend:'recommended',trend:'monthly',monthly:'monthly',new:'new',good:'good',change:'change'};state.filter=map[m.mode]||'recommended';filterButtons();render();return}if(m.type==='emu-knowledge-open-library'){openPanel('library');return}if(m.type==='emu-knowledge-loading'){if(!m.append)$('#posts').innerHTML=`<section class="card empty"><p>${esc(emuT('k.loadingPosts'))}</p></section>`;return}if(m.type==='emu-knowledge-error'){notify(m.error||emuT('k.toast.loadFailed'));return}if(m.type==='emu-knowledge-notice'){notify(m.text||'');return}if(m.type==='emu-knowledge-prefill'){openComposer();const t=$('#body');if(t){t.value=m.body||'';t.focus();}return}if(m.type==='emu-knowledge-authors'){Object.assign(state.authors,m.authors||{});render();return}if(m.type==='emu-knowledge-posts'){Object.assign(state.authors,m.authors||{});state.posts=m.append?[...state.posts,...m.posts]:m.posts||[];if(!m.append)state.totalCount=(typeof m.totalCount==='number')?m.totalCount:null;state.account=m.account||'';state.isOwner=!!m.isOwner;state.monthlyTheme=m.monthlyTheme||'はじめる';state.monthlyCopy=m.monthlyCopy||'';state.drafts=m.drafts||[];state.scheduledCount=m.scheduledCount||0;state.helpedCount=m.helpedCount||0;if(!m.append)state.conclusions=m.conclusions||[];state.canDraft=!!m.canDraft;state.canSchedule=!!m.canSchedule;state.hasMore=!!m.hasMore;state.guestCapped=!!m.guestCapped;state.guestLimit=m.guestLimit||0;$('#draft').hidden=!state.canDraft;$('#schedule').hidden=!state.canSchedule;$('#scheduleField').hidden=!state.canSchedule;themeButtons();render();window.EmuAnalytics?.view('knowledge_list_view',{surface:'feed'});return}if(m.type==='emu-knowledge-panel-data'){renderPanel(m.kind,m.items||[]);return}if(m.type==='emu-knowledge-save-result'){if(state.pending&&m.requestId===state.pending.requestId)finish(!!m.ok,m.error);if(m.drafts)state.drafts=m.drafts;render();return}if(m.type==='emu-knowledge-drafts-page'){const list=$(m.source==='lab'?'#labDraftList':'#emuDraftList'),wrap=document.querySelector(`[data-more-wrap="${m.source==='lab'?'lab':'emu'}"]`);if(list){if(m.source!=='lab')state.panelDrafts=[...(state.panelDrafts||[]),...(m.items||[])];list.insertAdjacentHTML('beforeend',(m.items||[]).map(draftRow).join(''))}if(wrap){if(m.next){wrap.querySelector('button').dataset.cursor=m.next;wrap.querySelector('button').disabled=false}else wrap.remove()}bindDraftActions();return}if(m.type==='emu-knowledge-drafts'){state.drafts=m.drafts||[];render();if($('#panel').classList.contains('open'))openPanel('library');return}if(m.type==='emu-knowledge-reaction-result'){notify(m.ok?emuT('k.toast.reacted'):m.error||emuT('k.toast.reactFailed'));if(!m.ok)render()}});
